'use strict';
const C=ReportsCore, KEY='sion-reports-private-test-v2';
const months=['Janeiro','Fevereiro','Março','Abril','Maio','Junho','Julho','Agosto','Setembro','Outubro','Novembro','Dezembro'];
const short=['JAN','FEV','MAR','ABR','MAI','JUN','JUL','AGO','SET','OUT','NOV','DEZ'];
const clone=x=>JSON.parse(JSON.stringify(x));
let db=clone(SEED), storageOK=true;

let state={view:'dashboard',user:PORTAL.user.id,owner:SEED.owners[0]?.id||'',year:2026,report:null,property:'1',preview:false,includeHistory:true,chart:'bar',modal:null};
const e=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>n===null||n===undefined?'—':new Intl.NumberFormat('pt-BR',{style:'currency',currency:'USD'}).format(n/100);
const dec=n=>n===null||n===undefined?'':(n/100).toFixed(2);
const user=()=>db.users.find(x=>x.id===state.user)||db.users[0];
const admin=()=>['admin','editor'].includes(user().role);
const allowedOwnerIds=u=>(u.ownerIds||[]).filter(id=>!db.owners.find(o=>o.id===id)?.blocked);
const blockedAccess=u=>!!u.blocked||(!['admin','editor'].includes(u.role)&&allowedOwnerIds(u).length===0);
const owner=()=>db.owners.find(x=>x.id===state.owner)||db.owners[0];
const prop=id=>db.properties.find(x=>x.id===id)||{name:'Imóvel removido',id};
const properties=()=>db.properties.filter(x=>x.ownerId===state.owner);
const reports=()=>db.reports.filter(x=>x.ownerId===state.owner&&x.year===Number(state.year)).sort((a,b)=>b.month-a.month);
const report=()=>db.reports.find(x=>x.id===state.report&&x.ownerId===state.owner);
const visibleReports=()=>reports().filter(x=>admin()||x.status==='published'||(state.includeHistory&&x.historical));
const originalTotals=r=>r.historical?{received:r.controls.received,fee:r.controls.fees,expenses:r.controls.expenses,draw:r.controls.draw,net:null}:C.totals(r);
const badge=r=>r.status==='published'?'<span class="pill">Publicado</span>':r.historical?'<span class="pill warn">Histórico original</span>':'<span class="pill draft">Rascunho</span>';
const icon=type=>{const path={dashboard:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',reports:'<path d="M6 3h9l4 4v14H6zM14 3v6h5M9 13h7M9 17h7"/>',editor:'<path d="M4 20l4-1L20 7l-4-4L4 15zM13 6l4 4"/>',properties:'<path d="M3 10l9-7 9 7M5 9v12h14V9M10 21v-7h4v7"/>',access:'<circle cx="9" cy="7" r="4"/><path d="M2 21v-3a7 7 0 0 1 14 0v3M17 4a4 4 0 0 1 0 8M19 15a5 5 0 0 1 3 5"/>'}[type]||'<path d="M3 12h18M12 3v18"/>';return '<svg viewBox="0 0 24 24" aria-hidden="true">'+path+'</svg>';};
function toast(s){document.querySelector('.toast')?.remove();const n=document.createElement('div');n.className='toast';n.setAttribute('role','status');n.textContent=s;document.body.append(n);setTimeout(()=>n.remove(),5000);}
function save(){try{ServerStorage.setItem(KEY,JSON.stringify(db));storageOK=true;}catch(err){storageOK=false;toast('Não foi possível guardar no servidor. Exporte um backup antes de fechar.');}}
function actions(){return `<div class="actions"><button class="btn" data-act="pdf">Salvar PDF</button><button class="btn" data-act="xlsx">Salvar Excel</button><button class="btn" data-act="print">Imprimir</button></div>`;}
function pagehead(k,title,desc,extra=''){return `<div class="pagehead"><div><div class="eyebrow">${k}</div><h1>${title}</h1><p class="muted">${desc}</p></div>${extra}</div>`;}
function render(){
 if(false){document.getElementById('app').innerHTML=loginPage();return;}
 if(blockedAccess(user())){document.getElementById('app').innerHTML='<main class="blocked"><h1>Acesso bloqueado</h1><p>Este perfil foi bloqueado pela gestão Sion neste portal.</p><button class="btn" data-act="return-admin">Voltar à gestão de teste</button></main>';return;}

 if(!admin()&&!allowedOwnerIds(user()).includes(state.owner))state.owner=allowedOwnerIds(user())[0];
 if(!admin()&&!['dashboard','reports','statement','hoa'].includes(state.view))state.view='dashboard';
 const navigation=[['hoa','HOA anual'],['dashboard','Visão geral'],['reports','Relatórios'],...(admin()? [['annual','1099 / Acumulado'],['properties','Imóveis · Fotos e anúncios'],['access','Acessos']]:[])];
 document.getElementById('app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><img src="${SEED.logo}" alt="Sion Property Management"><small>PORTAL DO INVESTIDOR</small></div><nav class="nav" aria-label="Principal">${navigation.map(([id,label])=>`<button data-view="${id}" class="${state.view===id?'active':''}">${icon(id==='statement'?'reports':id)}${label}</button>`).join('')}</nav><div class="sidefoot"><strong>Transparência em cada detalhe.</strong>Seus imóveis. Seus resultados.<br><br>Futuro endereço:<br>sionrealtypm.com/reports</div></aside><div class="workspace"><header class="topbar"><div class="crumb">Sion / ${admin()?'Área de gestão':'Área do investidor'} ${admin()?'<button class="btn tiny" data-act="newowner">+ Novo investidor</button>':''}</div><div class="topcontrols"><select id="owner-select" aria-label="Investidor">${db.owners.filter(o=>admin()||allowedOwnerIds(user()).includes(o.id)).map(o=>`<option value="${e(o.id)}" ${o.id===state.owner?'selected':''}>${e(o.name)}</option>`).join('')}</select><span id="sync-status" role="status">Salvo no servidor</span><button class="btn tiny" data-logout>Sair</button><div class="avatar" title="${e(user().name)}">${e(user().name[0])}</div></div></header><main>${!storageOK?'<div class="notice">Armazenamento local indisponível. Faça backup antes de fechar.</div>':''}${content()}<footer class="footer"><span>Sion Property Management · Orlando, Florida</span><span>USD · Administração: percentual nos alugados e taxa manual nos disponíveis</span></footer></main></div></div>${modalHTML()}`;
}
function content(){switch(state.view){case'annual':return annualPage();case'hoa':return hoaPage();case'dashboard':return dashboard();case'reports':return reportlist();case'statement':return statement();case'editor':return editor();case'properties':return propertyPage();case'access':return accessPage();default:return dashboard();}}
function yearSelect(){return `<select id="year-select" aria-label="Ano" style="width:115px">${[...new Set([2026,2027,...db.reports.map(r=>r.year)])].sort().map(y=>`<option ${y===Number(state.year)?'selected':''}>${y}</option>`).join('')}</select>`;}
function stat(label,value,note,color){return `<div class="stat"><div class="label"><span class="dot" style="background:${color||'#bc9a55'}"></span>${label}</div><div class="number">${value}</div><small>${note}</small></div>`;}
function dashboard(){
 const list=visibleReports(), ts=list.map(originalTotals), total=k=>C.sum(ts.map(x=>x[k]));
 const ps=properties(),occupied=ps.filter(p=>p.status==='occupied').length,vacant=ps.filter(p=>p.status==='vacant').length,unknown=ps.length-occupied-vacant;
 const historical=list.filter(r=>r.historical).length, drafts=reports().filter(r=>!r.historical&&r.status!=='published').length;
 const observed=Array.from({length:12},(_,i)=>{const rr=list.find(r=>r.month===i+1);return rr?originalTotals(rr).received:null;}),max=Math.max(...observed.filter(x=>x!==null),1);
 const a=total('fee'),b=total('expenses'),c=total('draw'),base=ps.length;
 const donut=base?`conic-gradient(#c1a269 0 ${occupied/base*100}%,#acbfad ${occupied/base*100}% ${(occupied+vacant)/base*100}%,#397961 ${(occupied+vacant)/base*100}% 100%)`:'#e6eae1';
 return pagehead('Seu patrimônio, com clareza',admin()?'Gestão que você acompanha.':'Seu investimento, em perspectiva.',`${e(owner().name)} · Resumo de ${state.year}`,`<div class="actions">${yearSelect()}${admin()?'<button class="btn primary" data-act="new">+ Novo relatório</button>':''}</div>`)+
 (!admin()&&!state.includeHistory?'<div class="notice info">Quer conferir como os relatórios antigos aparecerão? <button class="btn tiny" data-act="historypreview">Simular visão do histórico</button></div>':'')+(historical?`<div class="notice"><strong>Histórico importado.</strong> Os cards usam os totais informados nos ${historical} relatórios originais, preservados exatamente como enviados. Não recalculamos nem corrigimos o histórico.</div>`:'')+
 `<div class="hero"><div><div class="eyebrow">${admin()?'Sua operação em um só lugar':'Prestação de contas'}</div><h2>${ps.length} imóveis cadastrados. Uma visão do que importa.</h2><p class="muted">${occupied} alugados · ${vacant} disponíveis · ${unknown} com situação a confirmar. Recebimento zero no histórico não é tratado automaticamente como vacância.</p></div><span class="pill ${unknown?'warn':''}">${unknown?'Confirmar ocupação':'Cadastro atualizado'}</span></div>`+
 `<div class="stats">${stat('Aluguéis recebidos',money(total('received')),`${list.length} períodos nesta visão`,'#397961')}${stat('Administração',money(a),historical?'Valores informados no histórico':'10% dos alugados + taxas manuais dos disponíveis')}${stat('Despesas lançadas',money(b),'Somente despesas identificadas','#8fa58f')}${stat('Repasses informados',money(total('draw')),'Valores registrados pela gestão','#244c3d')}</div>`+
 `<div class="grid2"><section class="card"><div class="cardhead"><div><h2>Aluguéis recebidos por mês</h2><span class="small muted">${historical?'Histórico dos dados importados':'Relatórios publicados'} · USD · ${state.year}</span></div><span class="pill blue">Mensal</span></div><div class="bars" role="img" aria-label="Recebimentos mensais em dólares">${observed.map((v,i)=>`<div class="baritem"><div class="bar ${v===null?'alt':''}" style="height:${v===null?0:Math.max(2,v/max*160)}px" title="${months[i]}: ${v===null?'sem relatório':money(v)}"></div><small>${short[i]}</small></div>`).join('')}</div><div class="chartnote">Meses sem relatório ficam sem valor; não significam aluguel zero. <button class="btn tiny" data-act="chartdata">Ver valores</button></div></section><section class="card"><div class="cardhead"><div><h2>Ocupação atual</h2><span class="small muted">Situação atual confirmada pela gestão</span></div></div><div class="piearea"><div class="donut" style="background:${donut}" role="img" aria-label="Ocupação dos imóveis"><div class="donutlabel">Ocupação<strong>${base} imóveis</strong></div></div><div class="occupancy-legend"><div><span><i style="background:#c1a269"></i>Alugados</span><strong>${occupied}</strong></div><div><span><i style="background:#acbfad"></i>Disponíveis</span><strong>${vacant}</strong></div><div><span><i style="background:#397961"></i>A confirmar</span><strong>${unknown}</strong></div></div></div><p class="chartnote">Situação atual do cadastro; não representa a ocupação histórica.</p></section></div>`+
 `<section class="card"><div class="cardhead"><div><h2>Relatórios recentes</h2><span class="small muted">${admin()?`${drafts} períodos aguardando revisão ou publicação`:'Disponíveis para consulta e exportação'}</span></div><button class="btn tiny" data-view="reports">Ver todos →</button></div>${list.length?reportTable(list.slice(0,4)):'<div class="empty"><h2>Seus relatórios aparecerão aqui.</h2><p class="muted">Após a publicação pela equipe Sion, você poderá consultar e baixar PDF ou Excel.</p></div>'}</section>`+
 `<div class="grid2" style="margin-top:22px"><section class="card"><h2>Notas da gestão</h2><p class="muted small">Informações e comentários da equipe sobre os períodos apresentados.</p>${list.filter(r=>r.notes).slice(0,3).map(r=>`<p><strong>${months[r.month-1]}:</strong> ${e(r.notes)}</p>`).join('')||'<p class="muted">Ainda não há comentários publicados para este ano.</p>'}</section><section class="card"><h2>Repasses informados</h2><p style="font-size:27px;margin:18px 0 6px">${money(total('draw'))}</p><p class="muted small">Valores registrados como enviados ao proprietário. Podem diferir do resultado calculado por reservas, ajustes ou despesas ainda não classificadas.</p></section></div>`;
}
function reportTable(list){return `<div class="tablewrap"><table><thead><tr><th>Período</th><th>Situação</th><th class="num">Recebido</th><th class="num">Administração</th><th></th></tr></thead><tbody>${list.map(r=>{const t=originalTotals(r);return `<tr><td><strong>${months[r.month-1]} ${r.year}</strong><br><span class="muted">${e(r.period)}</span></td><td>${badge(r)}</td><td class="num">${money(t.received)}</td><td class="num">${money(t.fee)}</td><td class="num"><button class="btn tiny" data-open="${r.id}">${admin()&&r.status!=='published'?'Prévia':'Abrir'} →</button></td></tr>`;}).join('')}</tbody></table></div>`;}
function reportlist(){const list=visibleReports();return pagehead('Documentos do investidor','Relatórios mensais.','Selecione um período para consultar, imprimir ou exportar.',`<div class="actions">${yearSelect()}${admin()?'<button class="btn primary" data-act="new">+ Novo relatório</button><button class="btn" data-act="trash">Lixeira</button>':''}</div>`)+
 (admin()?'<div class="notice info">Janeiro a outubro de 2026 permanecem como enviados. Novembro começa em um novo rascunho, com todos os imóveis lado a lado.</div>':'')+
 `<div class="reportlist">${list.map(r=>{const t=originalTotals(r);return `<article class="reporttile">${badge(r)}<h2>${months[r.month-1]} ${r.year}</h2><div class="small muted">${e(r.period)}</div><div class="money">${money(t.received)}</div><span class="small muted">Aluguéis recebidos</span><div class="actions"><button class="btn primary" data-open="${r.id}">${admin()?'Ver relatório':'Consultar'}</button>${admin()&&!r.historical?`<button class="btn" data-edit="${r.id}">Preencher</button>`:''}</div>${r.historical?`<p class="small muted" style="margin-top:13px">Arquivos e valores originais preservados</p>`:''}</article>`;}).join('')||'<section class="card empty"><h2>Nenhum relatório publicado neste ano.</h2><p>O investidor vê somente os períodos liberados pela equipe.</p></section>'}</div>`;}
/* Horizontal statements and editor */
function propertyPage(){return pagehead('Cadastro permanente','Seus imóveis.','Situação de ocupação e aluguel contratado são confirmados pela equipe.',`<button class="btn primary" data-act="newproperty">+ Cadastrar imóvel</button>`)+`<div class="notice">Os endereços vieram das planilhas. O último recebimento positivo é uma referência: não presumimos que ele seja o aluguel contratado atual. Situações de ocupação começam como “A confirmar”.</div><section class="card"><div class="tablewrap"><table><thead><tr><th>Imóvel</th><th>Situação</th><th>Aluguel contratado (USD)</th></tr></thead><tbody>${properties().map(p=>`<tr><td><strong>${e(p.name)}</strong></td><td><select data-prop="${p.id}" data-key="status">${[['unknown','A confirmar'],['occupied','Alugado'],['vacant','Disponível']].map(([k,label])=>`<option value="${k}" ${k===p.status?'selected':''}>${label}</option>`).join('')}</select></td><td><input data-prop="${p.id}" data-key="rent" inputmode="decimal" value="${p.rentConfirmed?dec(p.rent):''}" placeholder="${p.rent!==null?'Referência: '+dec(p.rent):'Informar aluguel'}"></td></tr>`).join('')}</tbody></table></div></section>`;}
function accessPage(){return pagehead('Equipe e permissões','Acesso certo para cada pessoa.','Dez investidores previstos, com contas adicionais de consulta para contadores.',`<div class="actions"><button class="btn" data-act="backup">Exportar backup</button><button class="btn primary" data-act="newowner" ${db.owners.length>=10?'disabled':''}>+ Investidor</button><button class="btn" data-act="newuser">+ Novo usuário</button></div>`)+`<div class="notice"><strong>Perfis de demonstração.</strong> Este arquivo permite trocar de perfil para testar as telas. Não cria contas reais, senhas ou proteção de dados. A versão no servidor terá login, permissões e isolamento por investidor antes de ser disponibilizada aos clientes.</div><div class="accessgrid">${Array.from({length:10},(_,i)=>`<div class="slot ${db.owners[i]?'filled':''}"><span class="eyebrow">Investidor ${String(i+1).padStart(2,'0')}</span><strong>${e(db.owners[i]?.name||'Disponível')}</strong><span class="small muted">${db.owners[i]?'Cadastro de teste':'Aguardando cadastro'}</span>${db.owners[i]?`<span class="pill ${db.owners[i].blocked?'warn':''}">${db.owners[i].blocked?'✕ Sem acesso':'✓ Acesso permitido '}</span><button class="btn tiny ${db.owners[i].blocked?'':'danger'}" data-act="block-owner" data-oid="${e(db.owners[i].id)}">${db.owners[i].blocked?'Desbloquear':'✕ Bloquear acesso'}</button>`:''}</div>`).join('')}</div><section class="card"><h2>Perfis cadastrados </h2><div class="tablewrap"><table><thead><tr><th>Pessoa</th><th>Perfil</th><th>Pode alterar?</th><th>Relatórios permitidos</th><th>Acesso</th></tr></thead><tbody>${db.users.map(u=>`<tr><td>${e(u.name)}<br><span class="small muted">${e(u.email||"E-mail a cadastrar")}<br>${e(u.invitation||"Perfil de demonstração")}</span></td><td>${({admin:'Administrador',editor:'Equipe',investor:'Investidor',accountant:'Contador'})[u.role]}</td><td>${['admin','editor'].includes(u.role)?'Sim':'Não · somente consulta'}</td><td>${['admin','editor'].includes(u.role)?'Todos (gestão)':u.ownerIds.map(id=>e(db.owners.find(o=>o.id===id)?.name||id)).join(', ')}</td><td>${u.role==='admin'?'Administrador':`<span class="pill ${u.blocked?'warn':''}">${blockedAccess(u)?'✕ Sem acesso':'✓ Ativo '}</span><button class="btn tiny" data-act="block-user" data-uid="${e(u.id)}">${u.blocked?'Desbloquear':'Bloquear'}</button>`}</td></tr>`).join('')}</tbody></table></div><p class="muted small" style="margin-top:18px">Bloquear o cartão do investidor suspende, neste portal, todos os perfis de consulta vinculados a ele, inclusive contador. O botão da pessoa bloqueia apenas aquele usuário. Bloqueio permanece até Desbloquear. A contadora VTR consulta somente os relatórios da VTR. Outros investidores não ficam visíveis automaticamente. Arquivos Excel/PDF baixados são cópias e não alteram o portal.</p></section>`;}
function modalHTML(){if(!state.modal)return '';let body='';if(state.modal==='new')body=`<h2>Novo relatório</h2><form id="new-form"><div class="formgrid"><label>Mês<select name="month">${months.map((m,i)=>`<option value="${i+1}" ${i===10?'selected':''}>${m}</option>`).join('')}</select></label><label>Ano<input name="year" type="number" min="2026" max="2100" value="${state.year}"></label></div><p class="small muted">Aluguéis confirmados e saldos finais de relatórios publicados anteriores são reaproveitados. Recebimentos começam em branco. Saldos anteriores ausentes precisam ser confirmados.</p><div class="actions"><button type="button" data-act="create-draft" class="btn primary">Criar rascunho</button><p class="small" id="draft-result" role="status"></p><button type="button" class="btn" data-act="close">Cancelar</button></div></form>`;
 if(state.modal==='newproperty')body=`<h2>Cadastrar imóvel</h2><form id="property-form"><label>Endereço / identificação<input name="name" required maxlength="180"></label><label style="margin-top:14px">Aluguel contratado em USD (opcional)<input name="rent" inputmode="decimal" placeholder="1700.00"></label><label style="margin-top:14px">Situação<select name="status"><option value="unknown">A confirmar</option><option value="occupied">Alugado</option><option value="vacant">Disponível</option></select></label><p class="small muted">Investidor: ${e(owner().name)}. Aparecerá nos novos relatórios.</p><div class="actions"><button class="btn primary">Cadastrar</button><button type="button" class="btn" data-act="close">Cancelar</button></div></form>`;
 if(state.modal==='newowner')body='<h2>Cadastrar investidor</h2><form id="owner-form"><label>Nome completo / empresa<input name="name" required maxlength="100"></label><label>E-mail<input name="email" type="email"></label><label>Primeiro imóvel (opcional)<input name="property"></label><label>Aluguel contratado USD<input name="rent" inputmode="decimal"></label><p class="small muted">Este cadastro não cria senha ou envia convite.</p><div class="actions"><button class="btn primary">Cadastrar </button><button type="button" class="btn" data-act="close">Cancelar</button></div></form>';
 if(state.modal==='newuser')body=`<h2>Novo usuário / convite</h2><form id="user-form"><label>Nome completo<input name="name" required maxlength="100"></label><label>E-mail para convite<input name="email" type="email" required></label><label style="margin-top:14px">Perfil<select name="role"><option value="investor">Investidor — consulta</option><option value="accountant">Contador — consulta</option><option value="editor">Equipe / esposa — edição</option></select></label><label style="margin-top:14px">Investidor permitido<select name="ownerId">${db.owners.map(o=>`<option value="${e(o.id)}" ${o.id===state.owner?'selected':''}>${e(o.name)}</option>`).join('')}</select></label><p class="small muted">O teste registra o convite, sem enviar e-mail nem criar senha. No servidor, o destinatário definirá a própria senha. Um contador recebe acesso explícito ao investidor selecionado. Perfil da equipe pode preencher todos os relatórios.</p><div class="actions"><button class="btn primary">Preparar convite </button><button type="button" class="btn" data-act="close">Cancelar</button></div></form>`;
 if(state.modal==='chartdata')body=`<h2>Recebimentos de ${state.year}</h2><table><thead><tr><th>Mês</th><th class="num">Recebido (USD)</th></tr></thead><tbody>${visibleReports().slice().reverse().map(r=>`<tr><td>${months[r.month-1]}</td><td class="num">${money(C.totals(r).received)}</td></tr>`).join('')}</tbody></table><button class="btn" data-act="close" style="margin-top:20px">Fechar</button>`;
 if(state.modal==='publish-report')body=`<h2>Publicar para o investidor?</h2><p>O relatório ficará disponível aos perfis permitidos neste portal. Depois você pode retirar a publicação, voltar a preencher ou excluir o rascunho.</p><div class="actions"><button class="btn primary" data-act="confirm-publish">Confirmar publicação</button><button class="btn" data-act="close">Cancelar</button></div>`;
 if(state.modal==='unpublish-report')body=`<h2>Retirar da visão do investidor?</h2><p>O relatório continuará salvo como rascunho para você editar ou excluir. O investidor deixará de vê-lo neste portal.</p><div class="actions"><button class="btn primary" data-act="confirm-unpublish">Retirar publicação</button><button class="btn" data-act="close">Cancelar</button></div>`;
 if(state.modal==='delete-report'){const r=report();body=`<h2>Excluir rascunho?</h2><p>${e(owner().name)} · ${months[r.month-1]} ${r.year}</p><p>O relatório sairá da lista e você poderá criar o mesmo mês novamente. Uma cópia ficará na lixeira do teste para recuperação.</p><div class="actions"><button class="btn danger" data-act="confirm-delete-report">Excluir e liberar o mês</button><button class="btn" data-act="close">Cancelar</button></div>`;}
 if(state.modal==='trash')body=`<h2>Lixeira de relatórios</h2><p class="small muted">Rascunhos excluídos de ${e(owner().name)}. Só é possível restaurar se não houver outro relatório do mesmo mês.</p>${(db.trash||[]).filter(t=>t.report.ownerId===state.owner).map(t=>`<div class="trash-item"><strong>${months[t.report.month-1]} ${t.report.year}</strong><button class="btn tiny" data-act="restore-report" data-trash-id="${e(t.id)}">Restaurar</button></div>`).join('')||'<p>Lixeira vazia.</p>'}<button class="btn" data-act="close">Fechar</button>`;
 return `<div class="modalback"><section class="modal" role="dialog" aria-modal="true" aria-label="Formulário">${body}</section></div>`;
}
function requireAdmin(){if(!admin()||blockedAccess(user()))throw Error('Este perfil não pode editar.');}
function createReport(m,y){requireAdmin();if(!Number.isInteger(m)||m<1||m>12||!Number.isInteger(y)||y<2026||y>2100)throw Error('Confira mês e ano.');const existing=db.reports.find(r=>r.ownerId===state.owner&&r.year===y&&r.month===m);if(existing){state.report=existing.id;state.year=y;state.view=existing.historical||existing.status==='published'?'statement':'editor';state.modal=null;render();toast('Relatório existente aberto.');return;}if(!properties().length)throw Error('Este investidor ainda não tem imóveis cadastrados.');
 const key=y*12+m,previous=db.reports.filter(r=>r.ownerId===state.owner&&r.status==='published'&&r.year*12+r.month<key).sort((a,b)=>(b.year*12+b.month)-(a.year*12+a.month))[0];
 const r={id:state.owner+'-'+y+'-'+String(m).padStart(2,'0'),ownerId:state.owner,year:y,month:m,period:`01/${String(m).padStart(2,'0')}/${y} - ${new Date(y,m,0).getDate()}/${String(m).padStart(2,'0')}/${y}`,start:`${y}-${String(m).padStart(2,'0')}-01`,end:`${y}-${String(m).padStart(2,'0')}-${new Date(y,m,0).getDate()}`,statementDate:new Date().toLocaleDateString('en-CA'),status:'draft',historical:false,aggregated:true,notes:'',rows:properties().map(p=>{const old=previous?.rows.find(x=>x.propertyId===p.id);const occupancy=old?.status||p.status,contract=old?.contractRent??(p.rentConfirmed?p.rent:null);return {propertyId:p.id,propertyName:p.name,status:occupancy,contractRent:contract,expected:occupancy==='vacant'?0:contract,suggested:p.rent,opening:old?C.row(old).balance:null,receipts:[{date:'',amount:null,note:'Total do período',aggregate:true}],feeOverride:null,expenses:Array.from({length:3},()=>({description:'',amount:0})),draw:0,drawMode:'auto',notes:'',imported:false};})};db.reports.push(r);state.report=r.id;state.year=y;state.property=r.rows[0].propertyId;state.view='editor';state.modal=null;save();render();toast('Rascunho criado. Confirme aluguel e saldo inicial de cada imóvel.');}
function publish(){requireAdmin();const r=report();if(!r)return;const err=C.publicationErrors(r);if(err.length){toast(err.join(' '));return;}state.modal='publish-report';render();}

document.addEventListener('click',async event=>{const b=event.target.closest('button');if(!b)return;try{
 if(b.dataset.view){state.view=b.dataset.view;state.modal=null;render();return;}
 if(b.dataset.open){state.report=b.dataset.open;state.view='statement';render();return;}
 if(b.dataset.edit){requireAdmin();state.report=b.dataset.edit;state.view='editor';render();return;}
 if(b.dataset.property){state.property=b.dataset.property;render();return;}
 if(b.dataset.removeReceipt!==undefined){requireAdmin();report().rows.find(r=>r.propertyId===state.property).receipts.splice(Number(b.dataset.removeReceipt),1);save();render();return;}
 if(b.form?.id==='new-form'&&b.type==='submit'){event.preventDefault();createReport(Number(b.form.elements.month.value),Number(b.form.elements.year.value));return;}
 const act=b.dataset.act;if(!act)return;
 if(act==='return-admin'){state.user='patrick';state.view='access';render();return;}
 if(act==='login-demo'){const id=document.getElementById('demo-profile').value;const u=db.users.find(x=>x.id===id);if(blockedAccess(u))throw Error('Acesso bloqueado. Contate a gestão Sion.');state.user=id;state.view='dashboard';state.owner=u.ownerIds[0]||state.owner;render();return;}
 if(act==='recover-preview'||act==='activate-preview'){document.getElementById('login-message').textContent='Na versão do servidor, o e-mail cadastrado receberá um link temporário para '+(act==='recover-preview'?'redefinir':'criar')+' a senha. Este teste não envia mensagens.';return;}
 if(act==='create-draft'){const form=document.getElementById('new-form');try{createReport(Number(form.elements.month.value),Number(form.elements.year.value));}catch(err){const n=document.getElementById('draft-result');if(n)n.textContent=err.message;else toast(err.message);}return;}
 if(act==='block-owner'){requireAdmin();const o=db.owners.find(x=>x.id===b.dataset.oid);if(!o)throw Error('Investidor não encontrado.');o.blocked=!o.blocked;save();render();toast(o.blocked?'Investidor sem acesso neste portal.':'Acesso do investidor permitido neste portal.');return;}
 if(act==='delete-report'){requireAdmin();const r=report();if(!r||r.historical)throw Error('O histórico original é preservado.');if(r.status==='published')throw Error('Retire da visão do investidor antes de excluir.');state.modal='delete-report';render();return;}
 if(act==='confirm-delete-report'){trashReport();return;}
 if(act==='trash'){requireAdmin();state.modal='trash';render();return;}
 if(act==='restore-report'){restoreReport(b.dataset.trashId);return;}
 if(act==='block-user'){requireAdmin();const u=db.users.find(x=>x.id===b.dataset.uid);if(!u||u.id===state.user||u.role==='admin')throw Error('Não é permitido bloquear o administrador neste portal.');u.blocked=!u.blocked;save();render();toast(u.blocked?'Perfil bloqueado neste portal.':'Perfil desbloqueado neste portal.');return;}
 if(['new','newowner','newuser','newproperty'].includes(act)){requireAdmin();state.modal=act;render();return;}
 if(act==='historypreview'){state.includeHistory=true;render();return;}if(act==='close'){state.modal=null;render();return;}if(act==='chartdata'){state.modal=act;render();return;}
 if(act==='publish'){if(document.querySelector('[aria-invalid=true]'))throw Error('Corrija os campos marcados antes de publicar.');publish();return;}
 if(act==='unpublish'){requireAdmin();state.modal='unpublish-report';render();return;}
 if(act==='confirm-publish'){finalizePublish();return;}
 if(act==='confirm-unpublish'){withdrawReport();return;}
 if(['addreceipt','addexpense','fillzero'].includes(act)){requireAdmin();const r=report();if(r.status==='published')throw Error('Retire a publicação antes de editar.');const x=r.rows.find(x=>x.propertyId===state.property);if(act==='addreceipt')x.receipts.push({date:'',amount:null,note:''});if(act==='addexpense')x.expenses.push({description:'',amount:0});if(act==='fillzero'&&confirm('Confirmar aluguel devido e saldo anterior ainda vazios como zero em todos os imóveis?'))for(const x of r.rows){if(x.expected===null)x.expected=0;if(x.opening===null)x.opening=0;for(const p of x.receipts)if(p.amount===null)p.amount=0;}save();render();return;}
 if(act==='draw-auto'){requireAdmin();const r=report();if(!r||r.historical||r.status==='published')throw Error('Relatório somente para consulta.');const x=r.rows.find(x=>x.propertyId===b.dataset.id);x.drawMode='auto';save();render();return;}
 if(act==='save-draft'){requireAdmin();save();toast(storageOK?'Rascunho salvo no servidor.':'Não foi possível salvar. Faça backup.');return;}
 if(act==='extra-grid'){requireAdmin();report().rows.forEach(x=>x.expenses.push({description:'',amount:0}));save();render();return;}
 if(act==='backup'){requireAdmin();download(new Blob([JSON.stringify(db)],{type:'application/json'}),'Sion-Backup-Teste.json');return;}
 const r=report();if(!r||(!admin()&&r.status!=='published'&&!(state.includeHistory&&r.historical)))throw Error('Relatório não autorizado.');
 if(act==='pdf'){toast('Preparando PDF...');await exportPDF(r);}if(act==='xlsx'){toast('Preparando Excel...');await exportXLSX(r);}if(act==='print')window.print();
 if(act==='original-pdf'||act==='original-xlsx'){requireAdmin();const ext=act==='original-pdf'?'pdf':'xlsx',encoded=ext==='pdf'?r.sourcePdf:r.sourceXlsx;download(new Blob([Uint8Array.from(atob(encoded),c=>c.charCodeAt(0))]),r.sourceName.replace(/\.xlsx$/,'.'+ext));}
 }catch(err){toast(err.message||'Não foi possível concluir.');}});
function handleDataChange(event){const el=event.target,live=event.type==='input';try{
 if(live&&['user-select','owner-select','year-select'].includes(el.id))return;
 if(el.id==='user-select'){state.user=el.value;state.view='dashboard';state.report=null;render();return;}
 if(el.id==='owner-select'){state.owner=el.value;state.report=null;state.view='dashboard';render();return;}
 if(el.id==='year-select'){state.year=Number(el.value);render();return;}
 if(!el.dataset.field&&!el.dataset.meta&&el.dataset.receipt===undefined&&el.dataset.expense===undefined&&!el.dataset.prop)return;
 requireAdmin();
 if(el.dataset.prop){const p=prop(el.dataset.prop);if(el.dataset.key==='status')p.status=el.value;else{const n=C.cents(el.value);if(n!==null&&n<0)throw Error('Aluguel não pode ser negativo.');p.rent=n;p.rentConfirmed=n!==null;}save();if(live)updateLiveTotals();return;}
 const r=report();if(!r||r.historical||r.status==='published')throw Error('Este relatório não está disponível para edição.');
 const x=r.rows.find(r=>r.propertyId===state.property);
 if(el.dataset.meta){r[el.dataset.meta]=el.value;if(['start','end'].includes(el.dataset.meta)&&r.start&&r.end){const fmt=d=>d.split('-').reverse().join('/');r.period=fmt(r.start)+' - '+fmt(r.end);}}
 if(el.dataset.field){const k=el.dataset.field,val=k==='notes'?el.value:C.cents(el.value);if(k!=='notes'&&k!=='opening'&&val!==null&&val<0)throw Error('Use valor não negativo.');x[k]=val;}
 if(el.dataset.receipt!==undefined){const p=x.receipts[Number(el.dataset.receipt)],k=el.dataset.key;const v=k==='amount'?C.cents(el.value):el.value;if(k==='amount'&&v!==null&&v<0)throw Error('Recebimento não pode ser negativo.');p[k]=v;}
 if(el.dataset.expense!==undefined){const p=x.expenses[Number(el.dataset.expense)],k=el.dataset.key,v=k==='amount'?(C.cents(el.value)??0):el.value;if(k==='amount'&&v<0)throw Error('Despesa não pode ser negativa.');p[k]=v;}
 save();if(live)updateLiveTotals();
 }catch(err){toast(err.message);el.setAttribute('aria-invalid','true');}}
function updateLiveTotals(){const r=report();if(state.view!=='editor'||!r||r.historical)return;const x=r.rows.find(x=>x.propertyId===state.property);if(!x)return;const v=C.row(x),values=[money(v.received),money(v.fee),money(v.expenses),money(v.net),v.balance===null?'A confirmar':v.balance<0?'Crédito '+money(-v.balance):money(v.balance)];document.querySelectorAll('.totalsbox strong').forEach((n,i)=>{n.textContent=values[i];});const fee=document.querySelector('input[data-live-fee]');if(fee)fee.value=money(Math.round(v.received/10));const nav=document.querySelector('.propertynav button.active small');if(nav)nav.textContent=money(v.received)+' recebido';}
document.addEventListener('input',handleDataChange);
document.addEventListener('change',handleDataChange);
document.addEventListener('submit',event=>{event.preventDefault();try{requireAdmin();const f=event.target,data=new FormData(f);if(f.id==='new-form')createReport(Number(data.get('month')),Number(data.get('year')));if(f.id==='property-form'){const name=String(data.get('name')).trim(),rent=C.cents(data.get('rent'));if(rent!==null&&rent<0)throw Error('Aluguel não pode ser negativo.');db.properties.push({id:'property-'+Date.now(),ownerId:state.owner,name,rent,rentConfirmed:rent!==null,status:String(data.get('status'))});state.modal=null;save();render();}if(f.id==='owner-form'){if(db.owners.length>=10)throw Error('Os dez espaços de teste já foram preenchidos.');const name=String(data.get('name')).trim();if(!name)return;const id='owner-'+Date.now();db.owners.push({id,name,email:String(data.get('email')||'')});if(data.get('property'))db.properties.push({id:'property-'+Date.now(),ownerId:id,name:String(data.get('property')),rent:C.cents(data.get('rent')),rentConfirmed:!!data.get('rent'),status:'unknown'});state.owner=id;state.modal=null;save();render();}if(f.id==='user-form'){const name=String(data.get('name')).trim(),role=String(data.get('role'));if(!name)return;db.users.push({id:'profile-'+Date.now(),name,email:String(data.get('email')||''),invitation:'Convite preparado — não enviado',role,ownerIds:role==='editor'?[]:[String(data.get('ownerId'))]});state.modal=null;save();render();}}catch(err){const box=document.querySelector('.modal');if(box){let n=box.querySelector('.formerror');if(!n){n=document.createElement('p');n.className='notice formerror';box.append(n);}n.textContent=err.message;}else toast(err.message);}});
function download(blob,name){const a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download=name;a.textContent='Baixar '+name;a.style.color='#fff';a.style.textDecoration='underline';document.querySelector('.toast')?.remove();const n=document.createElement('div');n.className='toast';n.setAttribute('role','status');n.append(document.createTextNode('Arquivo pronto. Se o download não iniciar: '),a);document.body.append(n);a.click();setTimeout(()=>{URL.revokeObjectURL(url);n.remove();},300000);}
function filename(r,ext){return `Sion-${r.ownerId}-${r.year}-${String(r.month).padStart(2,'0')}${r.status==='published'?'':'-PREVIA'}.${ext}`;}
function statusOptions(value){return [['unknown','A confirmar'],['occupied','Alugado'],['vacant','Disponível']].map(([k,l])=>`<option value="${k}" ${value===k?'selected':''}>${l}</option>`).join('');}
function matrix(r,edit=false){
 const input=(x,k,val,placeholder='')=>edit?`<input data-grid="${e(x.propertyId)}" data-col="${k}" aria-label="${e(k+' — '+prop(x.propertyId).name)}" inputmode="${k==='notes'?'text':'decimal'}" value="${e(k==='notes'?val:dec(val))}" placeholder="${e(placeholder)}">`:e(k==='notes'?val:money(val));
 const line=(label,fn)=>`<tr><th>${label}</th>${r.rows.map(x=>`<td>${fn(x)}</td>`).join('')}</tr>`;
 const calc=k=>line(({fee:'Administração 10%',expenses:'Total de despesas',net:'Líquido calculado',balance:'Saldo final do inquilino'})[k],x=>`<strong data-calc="${k}" data-id="${e(x.propertyId)}">${money(C.row(x)[k])}</strong>`);
 return `<div class="matrixwrap"><table class="matrix"><thead><tr><th>Valores em USD ↓<br>Imóveis →</th>${r.rows.map(x=>`<th>${e(x.propertyName||prop(x.propertyId).name)}</th>`).join('')}</tr></thead><tbody>`+
 line('Situação',x=>r.historical?historicalStatusCell(r,x):edit?`<select data-grid="${e(x.propertyId)}" data-col="status" aria-label="Situação — ${e(prop(x.propertyId).name)}">${statusOptions(x.status||'unknown')}</select>`:({occupied:'Alugado',vacant:'Disponível',unknown:'A confirmar'})[x.status||'unknown'])+
 (!r.historical?line('Aluguel contratado',x=>input(x,'contractRent',x.contractRent,'Confirmar no cadastro'))+line('Aluguel devido no mês',x=>input(x,'expected',x.expected))+line('Saldo anterior',x=>input(x,'opening',x.opening,'Informar 0 ou saldo')):'')+
 line('Aluguel recebido',x=>input(x,'received',C.row(x).received===0&&x.receipts.every(z=>z.amount===null)?null:C.row(x).received,'Total recebido no mês'))+
 (r.historical?line('Administração informada',x=>money(C.row(x).fee)):line('Administração',x=>`<div data-admin-cell="${e(x.propertyId)}">${adminCell(x,edit)}</div>`))+
 Array.from({length:Math.max(3,...r.rows.map(x=>x.expenses.length))},(_,i)=>line('Despesa '+(i+1),x=>{const a=x.expenses[i]||{description:'',amount:0};return edit?`<input data-grid="${e(x.propertyId)}" data-col="expense-name-${i}" aria-label="Descrição ${i+1} — ${e(prop(x.propertyId).name)}" value="${e(a.description)}" placeholder="Descrição livre"><input data-grid="${e(x.propertyId)}" data-col="expense-value-${i}" aria-label="Valor ${i+1} — ${e(prop(x.propertyId).name)}" inputmode="decimal" value="${dec(a.amount)}">`:`${e(a.description)}<br>${money(a.amount)}`;})).join('')+calc('expenses')+(!r.historical?calc('net'):'')+
 line('Repasse realizado',x=>input(x,'draw',C.row(x).draw)+(edit?`<small data-draw-mode="${e(x.propertyId)}">${x.drawMode==='auto'?'Automático · igual ao líquido':'Valor editado'}</small><button class="btn tiny" data-act="draw-auto" data-id="${e(x.propertyId)}">Usar líquido</button>`:''))+(!r.historical?calc('balance'):'')+line('Observação',x=>input(x,'notes',x.notes||''))+'</tbody></table></div>';
}
function editor(){const r=report();if(!r||r.historical)return pagehead('Preenchimento mensal','Todos os imóveis, lado a lado.','Crie um relatório para começar.','<button class="btn primary" data-act="new">+ Novo relatório</button>');if(r.status==='published')return statement();
 return pagehead('Lançamentos · '+e(owner().name),months[r.month-1]+' '+r.year,'Preencha os números abaixo de cada imóvel. Role a tabela para os lados.',`<div class="actions"><button class="btn primary" data-act="save-draft">Salvar rascunho</button><button class="btn" data-open="${r.id}">Conferir relatório</button></div>`)+
 `<div class="notice info">O aluguel contratado precisa ser confirmado no cadastro ou nesta tabela. Recebido é o total de aluguel pago neste período, inclusive atrasados. Alugado: administração de 10% do recebido. Disponível: informe a taxa de administração manualmente, inclusive 0 se não cobrar. Repasse começa igual ao líquido; ao editá-lo, seu valor passa a ser preservado. Não inclua caução. Saldo anterior em branco precisa ser confirmado; não usamos os arquivos antigos para inventar dívidas.</div><section class="card"><div class="formgrid"><label>Início<input type="date" data-meta="start" value="${e(r.start)}"></label><label>Fim<input type="date" data-meta="end" value="${e(r.end)}"></label></div><p class="savehint" id="save-state">Salvamento local automático a cada alteração · botão Salvar confirma a gravação</p>${matrix(r,true)}<div class="actions" style="margin-top:20px"><button class="btn" data-act="extra-grid">+ Linha de despesa para todos</button><button class="btn" data-act="fillzero">Confirmar campos vazios como zero</button></div><label style="margin-top:20px">Comentários da gestão<textarea data-meta="notes">${e(r.notes)}</textarea></label><div class="summarystrip" id="grid-totals">${gridTotals(r)}</div><div class="actions"><button class="btn primary" data-act="save-draft">Salvar rascunho</button><button class="btn gold" data-act="publish">Publicar para o investidor · teste</button><button class="btn danger" data-act="delete-report" aria-label="Excluir rascunho">🗑 Excluir rascunho</button></div><p class="small muted">O investidor só consulta os novos relatórios após a publicação . Alterações não são enviadas ao site.</p></section>`;
}
function gridTotals(r){const t=C.totals(r);return [['received','Recebido'],['fee','Administração'],['expenses','Despesas'],['net','Líquido']].map(([k,l])=>`<div><small>${l}</small><strong>${money(t[k])}</strong></div>`).join('');}
function statement(){const r=report();if(!r||(!admin()&&r.status!=='published'&&!r.historical))return '<section class="card">Relatório indisponível.</section>';const t=originalTotals(r);return pagehead('Relatório mensal',months[r.month-1]+' '+r.year,e(owner().name),`<div class="actions"><button class="btn" data-view="reports">← Relatórios</button>${admin()&&!r.historical?`<button class="btn" data-edit="${r.id}">Preencher</button>`:''}${actions()}</div>`)+`<article class="card statement"><div class="reporttitle"><img src="${SEED.logo}" alt="Sion Property Management"><div><h2>Rental Owner Statement</h2><p>${e(owner().name)} · ${months[r.month-1]} ${r.year}</p>${badge(r)}</div></div>${r.historical?'<div class="notice info">Histórico preservado. Os totais abaixo são os informados no documento original, mesmo quando diferem da soma das linhas. PDF e Excel baixam exatamente os arquivos enviados.</div>':'<p class="small muted">Período: '+e(r.period)+' · Valores em USD</p>'}<div class="summarystrip">${[['received','Recebido'],['fee','Administração'],['expenses','Despesas'],['draw','Repasse informado']].map(([k,l])=>`<div><small>${l}</small><strong>${money(t[k])}</strong></div>`).join('')}</div>${matrix(r)}${admin()&&r.historical?'<p class="small muted">A situação pode ser corrigida por mês. Os valores, PDF e Excel originais são preservados.</p><button class="btn primary" data-act="save-draft">Salvar situações</button>':''}${r.notes?`<h3>Comentários da gestão</h3><p>${e(r.notes)}</p>`:''}${admin()&&!r.historical&&r.status==='published'?'<button class="btn screenonly" data-act="unpublish">Retirar da visão do investidor</button>':''}</article>`;}
function downloadOriginal(r,ext){const encoded=ext==='pdf'?r.sourcePdf:r.sourceXlsx;if(!encoded)throw Error('Original indisponível.');download(new Blob([Uint8Array.from(atob(encoded),c=>c.charCodeAt(0))],{type:ext==='pdf'?'application/pdf':'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'}),r.sourceName.replace(/\.xlsx$/,'.'+ext));}
function hoaRecord(create=false){db.hoa=db.hoa||[];let h=db.hoa.find(x=>x.ownerId===state.owner&&x.year===Number(state.year));if(!h&&create){h={ownerId:state.owner,year:Number(state.year),status:'draft',rows:properties().map(p=>({propertyId:p.id,budget:null,paid:Array(12).fill(null),notes:''}))};db.hoa.push(h);}return h;}
function hoaPage(){const h=hoaRecord();const canEdit=admin()&&h?.status!=='published';return pagehead('Condomínios · separado dos aluguéis','HOA anual',e(owner().name)+' · orçamento e pagamentos, sem dupla contagem no relatório de aluguel.',`<div class="actions">${yearSelect()}${admin()?'<button class="btn primary" data-hoa="create">Preparar ano</button>':''}</div>`)+`<section class="card"><div class="notice info">Histórico de HOA aguardando seus documentos. Nenhum valor foi presumido. Orçamento mensal × 12 é uma previsão; pagamentos são registrados por mês e ficam neste relatório separado.</div>${!h||(!admin()&&h.status!=='published')?'<p>Nenhum relatório HOA disponível para este ano.</p>':`<span class="pill">${h.status==='published'?'Publicado':'Rascunho'}</span><div class="matrixwrap"><table><thead><tr><th>Imóvel</th><th>Previsto / mês</th>${short.map(m=>'<th>'+m+'</th>').join('')}<th>Previsto / ano</th><th>Pago no ano</th><th>Previsto − pago</th><th>Observação</th></tr></thead><tbody>${h.rows.map(x=>{const field=(k,v)=>canEdit?`<input data-hoa-row="${e(x.propertyId)}" data-hoa-key="${k}" aria-label="HOA ${k} — ${e(prop(x.propertyId).name)}" value="${e(k==='notes'?v:dec(v))}" style="min-width:95px">`:e(k==='notes'?v:money(v));return `<tr><th>${e(prop(x.propertyId).name)}</th><td>${field('budget',x.budget)}</td>${x.paid.map((v,i)=>'<td>'+field(String(i),v)+'</td>').join('')}<td data-hoa-total="budget" data-id="${e(x.propertyId)}">${money(x.budget===null?null:x.budget*12)}</td><td data-hoa-total="paid" data-id="${e(x.propertyId)}">${money(C.sum(x.paid.map(v=>v||0)))}</td><td data-hoa-total="difference" data-id="${e(x.propertyId)}">${money(x.budget===null?null:x.budget*12-C.sum(x.paid.map(v=>v||0)))}</td><td>${field('notes',x.notes)}</td></tr>`;}).join('')}</tbody></table></div>${admin()?'<div class="actions"><button class="btn" data-hoa="save">Salvar HOA</button><button class="btn primary" data-hoa="publish">'+(h.status==='published'?'Voltar a rascunho':'Publicar HOA ')+'</button></div>':''}<button class="btn" onclick="window.print()">Imprimir / salvar PDF</button>`}</section>`;}
document.addEventListener('click',event=>{const b=event.target.closest('[data-hoa]');if(!b)return;try{requireAdmin();if(b.dataset.hoa==='create')hoaRecord(true);if(b.dataset.hoa==='publish'){const h=hoaRecord();if(h.status==='published')h.status='draft';else{if(h.rows.some(x=>x.budget===null||x.paid.some(v=>v===null)))throw Error('Informe orçamento e pagamentos de cada mês; use 0 quando confirmado sem pagamento.');h.status='published';}}save();render();toast('HOA salvo  local.');}catch(err){toast(err.message);}});
function matrixChange(event){const el=event.target;if(!el.dataset.grid&&!el.dataset.hoaRow)return;try{requireAdmin();if(el.dataset.hoaRow){const h=hoaRecord();if(h.status==='published')throw Error('Volte a rascunho para editar.');const x=h.rows.find(x=>x.propertyId===el.dataset.hoaRow),k=el.dataset.hoaKey;const v=k==='notes'?el.value:C.cents(el.value);if(k!=='notes'&&v!==null&&v<0)throw Error('Use valor não negativo.');if(k==='budget'||k==='notes')x[k]=v;else x.paid[Number(k)]=v;for(const n of document.querySelectorAll('[data-hoa-total]'))if(n.dataset.id===x.propertyId){const paid=C.sum(x.paid.map(v=>v||0));n.textContent=money(n.dataset.hoaTotal==='paid'?paid:x.budget===null?null:n.dataset.hoaTotal==='budget'?x.budget*12:x.budget*12-paid);}save();return;}
 const r=report();if(!r||r.historical||r.status==='published')throw Error('Relatório somente para consulta.');const x=r.rows.find(x=>x.propertyId===el.dataset.grid),k=el.dataset.col;let v=['status','notes'].includes(k)||k.startsWith('expense-name')?el.value:C.cents(el.value);if(typeof v==='number'&&v<0&&k!=='opening'&&k!=='draw')throw Error('Use valor não negativo.');
 if(k==='feeOverride'&&x.status!=='vacant')throw Error('A administração dos imóveis alugados é automática.');
 if(k==='draw'){x.drawMode=v===null?'auto':'manual';}
 if(k==='status'&&v!==x.status){x.feeOverride=null;}
 if(k==='received'){x.receipts=[{date:'',amount:v,aggregate:true,note:'Total do período'}];r.aggregated=true;}else if(k.startsWith('expense-')){const i=Number(k.split('-')[2]);while(x.expenses.length<=i)x.expenses.push({description:'',amount:0});x.expenses[i][k.startsWith('expense-name')?'description':'amount']=v??0;}else{x[k]=v;if(k==='status'||k==='contractRent'){x.expected=x.status==='vacant'?0:x.contractRent;const cell=document.querySelector(`[data-grid="${x.propertyId}"][data-col="expected"]`);if(cell)cell.value=dec(x.expected);}}
 const ac=document.querySelector(`[data-admin-cell="${x.propertyId}"]`);if(ac&&k==='status')ac.innerHTML=adminCell(x,true);
 const di=document.querySelector(`[data-grid="${x.propertyId}"][data-col="draw"]`);if(di&&k!=='draw'&&x.drawMode==='auto')di.value=dec(C.row(x).draw);const dm=document.querySelector(`[data-draw-mode="${x.propertyId}"]`);if(dm)dm.textContent=x.drawMode==='auto'?'Automático · igual ao líquido':'Valor editado';
 save();el.removeAttribute('aria-invalid');for(const n of document.querySelectorAll('[data-calc]'))if(n.dataset.id===x.propertyId)n.textContent=money(C.row(x)[n.dataset.calc]);const t=document.getElementById('grid-totals');if(t)t.innerHTML=gridTotals(r);const hint=document.getElementById('save-state');if(hint)hint.textContent=storageOK?'Salvo no servidor às '+new Date().toLocaleTimeString('pt-BR'):'Falha ao salvar — faça backup';
 }catch(err){el.setAttribute('aria-invalid','true');toast(err.message);}}
document.addEventListener('input',matrixChange);document.addEventListener('change',matrixChange);

// Add new owner labels without replacing saved financial records.
for(const o of SEED.owners){const existing=db.owners.find(x=>x.id===o.id);if(existing)existing.name=o.name;else db.owners.push(clone(o));}

for(const r of db.reports){if(!r.historical&&r.status==='draft')for(const x of r.rows){if(!x.drawMode)x.drawMode=(x.draw===0||x.draw===null)?'auto':'manual';}}
render();

function adminCell(x,edit){if(x.status==='vacant')return edit?`<input data-grid="${e(x.propertyId)}" data-col="feeOverride" aria-label="Administração — ${e(prop(x.propertyId).name)}" inputmode="decimal" value="${dec(x.feeOverride)}" placeholder="Informe a taxa"><small>Taxa manual</small>`:`<strong>${money(C.row(x).fee)}</strong><small>Taxa manual</small>`;return `<strong data-calc="fee" data-id="${e(x.propertyId)}">${money(C.row(x).fee)}</strong><small>${x.status==='occupied'?'Automático · 10% do recebido':'Confirme a situação'}</small>`;}

function trashReport(){requireAdmin();const r=report();if(!r||r.historical||r.status!=='draft')throw Error('Só é possível excluir um rascunho novo.');if(db.reports.some(x=>x.ownerId===r.ownerId&&x.status==='published'&&x.year*12+x.month>r.year*12+r.month))throw Error('Há relatório posterior publicado. Retire a publicação dos períodos seguintes antes de refazer este mês.');db.trash=db.trash||[];db.trash.push({id:'trash-'+Date.now()+'-'+Math.random().toString(36).slice(2),deletedAt:new Date().toISOString(),report:clone(r)});db.reports=db.reports.filter(x=>x!==r);state.report=null;state.modal=null;state.view='reports';save();render();toast('Rascunho excluído. O mês está livre para refazer.');}
function restoreReport(id){requireAdmin();const t=(db.trash||[]).find(t=>t.id===id&&t.report.ownerId===state.owner);if(!t)throw Error('Relatório não encontrado na lixeira.');const r=t.report;if(db.reports.some(x=>x.ownerId===r.ownerId&&x.year===r.year&&x.month===r.month))throw Error('Já existe um relatório deste mês. Exclua o novo rascunho antes de restaurar o anterior.');db.reports.push(clone(r));db.trash=db.trash.filter(x=>x!==t);state.report=r.id;state.year=r.year;state.view='editor';state.modal=null;save();render();toast('Rascunho restaurado.');}

function finalizePublish(){requireAdmin();const r=report();if(!r)throw Error('Relatório não encontrado.');const errors=C.publicationErrors(r);if(errors.length)throw Error(errors.join(' '));r.status='published';r.publishedAt=new Date().toISOString();state.modal=null;state.view='statement';save();render();toast('Relatório publicado.');}
function withdrawReport(){requireAdmin();const r=report();if(!r||r.historical)throw Error('O histórico original é preservado.');if(db.reports.some(x=>x.ownerId===r.ownerId&&x.status==='published'&&x.year*12+x.month>r.year*12+r.month))throw Error('Há relatório posterior publicado. Retire a publicação dos períodos seguintes antes de refazer este mês.');r.status='draft';state.modal=null;state.view='editor';save();render();toast('Retirado da visão do investidor. Rascunho disponível para editar ou excluir.');}

function historicalStatusCell(r,x){const value=db.historicalOccupancy?.[r.id]?.[x.propertyId]||x.status||'unknown';return admin()?`<select data-history-report="${e(r.id)}" data-history-property="${e(x.propertyId)}" aria-label="Situação histórica — ${e(x.propertyName||prop(x.propertyId).name)}">${statusOptions(value)}</select><small>Só a situação deste mês</small>`:({occupied:'Alugado',vacant:'Disponível',unknown:'A confirmar'})[value];}
document.addEventListener('change',event=>{const el=event.target;if(!el.dataset.historyReport)return;try{requireAdmin();const r=db.reports.find(r=>r.id===el.dataset.historyReport&&r.ownerId===state.owner&&r.historical);if(!r||!r.rows.some(x=>x.propertyId===el.dataset.historyProperty)||!['unknown','occupied','vacant'].includes(el.value))throw Error('Situação inválida.');db.historicalOccupancy=db.historicalOccupancy||{};db.historicalOccupancy[r.id]=db.historicalOccupancy[r.id]||{};db.historicalOccupancy[r.id][el.dataset.historyProperty]=el.value;save();toast('Situação do mês registrada. Valores e arquivos originais preservados.');}catch(err){toast(err.message);}});
